bool insidecircle(vec2 vec, vec2 circle, float radius)
{
    float d = distance(vec, circle) - radius;
    if (d <= 0.0 && d > -0.05*radius){
        return true;
    }else{
        return false;
    }
}

vec2 getnorm(vec2 pos, vec2 circle){
    return normalize(pos-circle);
}

vec3 lightcalc(vec2 pos, vec2 circle, float radius, vec2 lightpos)
{

    if(!insidecircle(pos, circle, radius)){
        //not in circle
        return vec3(0.0);

    }else{
        //we're in circle
        vec2 norm = getnorm(pos, circle);
        float diffuse = dot(normalize(lightpos-pos), norm);
        return vec3(diffuse);
    }
}



bool inshadow(vec2 pos, vec2 circle, float radius, vec2 lightpos)
{

    //if (distance(pos,circle) <= radius) return true;

    vec2 ptolight = pos - lightpos;
    float a = pow(ptolight.x, 2.0) + pow(ptolight.y, 2.0);
    float b = 2.*ptolight.x*(lightpos.x - circle.x) + 2.*ptolight.y*(lightpos.y - circle.y);
    float c = pow(lightpos.x-circle.x, 2.0) + pow(lightpos.y-circle.y, 2.0) - pow(radius, 2.0);
    float disc = b*b - 4.*a*c;
    float t = 2.*c/((-1.*b)+sqrt(disc));

    if (disc <= 0.0) return false;
    if (t < 0.0 || t > 1.0) return false;

    return true;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;
    uv *= 2.;
    uv -= 1.;

    vec2 mousepos = 2.*(iMouse.xy/iResolution.y) - 1.;
    vec2 lightpos = vec2(mousepos.x, mousepos.y);

    vec2 circle = vec2(1., 0.0);
    float radius = 0.4;
    float d = distance(lightpos, uv);
    float color = inshadow(uv.xy, circle, radius, lightpos) ? 0.0 : 1.0;
    vec3 c = lightcalc(uv, circle, radius, lightpos);
    vec3 f = vec3(color);
    // Output to screen
    fragColor = vec4(c+f,1.0);
}
